import React, { useState, useEffect } from 'react';
import banner1 from '../../../assets/banner.png';
import banner2 from '../../../assets/banner.png';
import banner3 from '../../../assets/banner.png';

const banners = [banner1, banner2, banner3];

export default function BannerSlider() {
  const [current, setCurrent] = useState(0);

  // Auto-slide every 5 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrent((prev) => (prev + 1) % banners.length);
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="relative overflow-hidden my-6 px-[5vw]">
      <div
        className="flex transition-transform duration-700 ease-in-out"
        style={{ transform: `translateX(-${current * 100}%)`, width: `${banners.length * 100}%` }}
      >
        {banners.map((img, idx) => (
          <div key={idx} className="w-full flex-shrink-0 min-h-[60vh]">
            <img
              src={img}
              alt={`Slide ${idx + 1}`}
              className="w-full h-full object-cover rounded-2xl"
            />
          </div>
        ))}
      </div>

      {/* Dots */}
      <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex gap-2 z-10">
        {banners.map((_, idx) => (
          <button
            key={idx}
            onClick={() => setCurrent(idx)}
            className={`w-3 h-3 rounded-full transition-colors duration-300 ${
              idx === current ? 'bg-[#F48F0F]' : 'bg-gray-300'
            }`}
            aria-label={`Go to slide ${idx + 1}`}
          ></button>
        ))}
      </div>
    </div>
  );
}
